package com.wms.config;
import com.wms.dto.StockInRequest; import com.wms.model.entity.*; import com.wms.repository.*; import com.wms.service.InventoryService; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.core.env.Environment; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.BigDecimal; import java.util.Arrays;
@Configuration public class DemoDataConfig {
 @Bean CommandLineRunner demoData(Environment env,CategoryRepository categories,ItemRepository items,WarehouseRepository warehouses,InventoryService stock,UserAccountRepository users,PasswordEncoder passwords){return args->{String[] profiles=env.getActiveProfiles();boolean isDev=profiles.length==0||Arrays.asList(profiles).stream().anyMatch(p->p.equals("dev")||p.equals("test"));if(!isDev){// 生产环境不注入演示账号/物品，避免默认口令与演示数据进入真实库
      return;}if(users.count()==0){users.save(user("admin","管理员","ADMIN",passwords));users.save(user("operator","仓库操作员","WAREHOUSE",passwords));}if(items.count()>0)return;Category category=categories.save(new Category("电子设备"));Warehouse warehouse=warehouses.save(new Warehouse("WH-001","主仓库"));Item a=item("ITEM-001","工业传感器","个","TS-2026",category,new BigDecimal("30"));Item b=item("ITEM-002","控制模块","套","CM-88",category,new BigDecimal("20"));Item c=item("ITEM-003","连接线","条","CB-10M",category,new BigDecimal("50"));items.save(a);items.save(b);items.save(c);stock.stockIn(new StockInRequest("ITEM-001",new BigDecimal("100"),new BigDecimal("15.50"),warehouse.getId(),"A-01-01",null,"系统初始化"));stock.stockIn(new StockInRequest("ITEM-002",new BigDecimal("40"),new BigDecimal("88.00"),warehouse.getId(),"A-01-02",null,"系统初始化"));stock.stockIn(new StockInRequest("ITEM-003",new BigDecimal("20"),new BigDecimal("8.20"),warehouse.getId(),"A-01-03",null,"系统初始化"));};}
 private UserAccount user(String username,String displayName,String role,PasswordEncoder passwords){UserAccount u=new UserAccount();u.setUsername(username);u.setDisplayName(displayName);u.setRole(role);u.setPassword(passwords.encode(username.equals("admin")?"admin123":"operator123"));return u;}
 private Item item(String code,String name,String unit,String specs,Category category,BigDecimal safety){Item i=new Item();i.setCode(code);i.setName(name);i.setUnit(unit);i.setSpecs(specs);i.setCategory(category);i.setSafetyStock(safety);return i;}
}
